(async () => {
  const W = 950, Hh = 830, gap = 40, pad = 48;
  const frame = async (k, n) => {
    const f = frames[k]; let img = '';
    if (f.bg) { const b = await sharp(path.join(bgDir, 'L3JS_' + f.bg + '_950.png')).jpeg({ quality: 80 }).toBuffer(); img = '<img alt="" src="data:image/jpeg;base64,' + b.toString('base64') + '" style="position: absolute; inset: 0; width: ' + W + 'px; height: ' + Hh + 'px;">'; }
    return '<figure style="margin: 0; width: ' + W + 'px;"><div style="' + st({ position: 'relative', width: W + 'px', height: Hh + 'px', overflow: 'hidden', borderRadius: '16px', background: K.tint, boxShadow: '0 0 0 1px #D9DDD3, 0 10px 30px rgba(17,21,17,.10)', fontFamily: "'Geist', system-ui, sans-serif", color: K.ink, fontSize: '14px', lineHeight: '20px', fontVariantNumeric: 'tabular-nums' }) + '">' + img + f.html() + '</div><figcaption style="margin-top: 12px; font-size: 14px; line-height: 21px; color: #3B4540;"><b style="font-weight: 600; color: #111511;">' + n + '</b> · ' + esc(f.cap) + '</figcaption></figure>';
  };
  const split = [['Tabs: what and when', 'Schedule, Batches, a batch, a task, a treatment: pages in their own tabs, with the counts, dates and the full pig list. Each has Show in Farm view; a row\'s pin shows one pig.'], ['Farm view: where', 'The map, the places and their live state. No Schedule or task panels inside it. Pigs and Devices are layers; Edit layout stays here.'], ['A lens joins them', 'Show in Farm view turns on a lens: a strip under the bar with the task\'s progress and its legend, the task\'s pigs coloured on a faded map. Open page goes back; ✕ ends it.'], ['Pig level lives in the Farm view', 'Hover: her line in the task. Click: the pane with her part of the task, her execution log and her record. The pane is for one pig, or one device, nothing else.']];
  const body = '<h1 style="margin: 0; font-size: 28px; line-height: 36px; font-weight: 600; letter-spacing: -.02em;">Pages in tabs, the Farm view for where, joined by a lens</h1><div style="margin-top: 6px; font-size: 15px; line-height: 22px; color: #5D665F;">A task stays a page; Show in Farm view carries its progress onto the map, so you rarely switch back. Drawn over a real Farm view screen.</div>' +
    '<div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-top: 22px;">' + split.map((r, i) => '<div style="padding: 16px 18px; background: #FFFFFF; border: 1px solid #DFE4D8; border-radius: 16px;"><div style="font-size: 15px; font-weight: 600;">' + (i + 1) + '. ' + r[0] + '</div><div style="margin-top: 4px; font-size: 14px; line-height: 21px; color: #3B4540;">' + esc(r[1]) + '</div></div>').join('') + '</div>' +
    '<div style="display: flex; gap: ' + gap + 'px; align-items: flex-start; margin-top: 36px;">' + (await Promise.all(['t1', 't2', 't3', 't4'].map((k, i) => frame(k, i + 1)))).join('') + '</div>';
  const BW = 4 * W + 3 * gap + 2 * pad;
  const sh = fs.readFileSync(shell, 'utf8'), pre = sh.slice(0, sh.indexOf('<div style="width: 1760px;')).replace(/<title>[^<]*<\/title>/, '<title>Pages and the Farm view</title>');
  const html = pre + '<div style="width: ' + BW + 'px; padding: 40px ' + pad + 'px 64px; box-sizing: border-box; background: #F3F4F1; font-family: \'Geist\', system-ui, sans-serif; color: #111511; -webkit-font-smoothing: antialiased;">' + body + '</div>\n</x-dc>\n</body>\n</html>\n';
  fs.writeFileSync(out, html); console.log('wrote', out, Math.round(html.length / 1024) + ' KB', 'width', BW);
})();
